package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_nullValue_TriageGen0Test {

    @Test
    public void testNullValue_NoDeferredName() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        writer.nullValue();

        assertEquals("null", out.toString());
    }

    @Test
    public void testNullValue_WithDeferredName_AndSerializeNullsTrue() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.setSerializeNulls(true);

        // Use name() to set deferredName
        writer.name("testKey");
        writer.nullValue();

        // Expected: "testKey":null
        assertEquals("{\"testKey\":null}", out.toString());
    }

    @Test
    public void testNullValue_WithDeferredName_AndSerializeNullsFalse() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.setSerializeNulls(false);

        // Use name() to set deferredName
        writer.name("testKey");

        // When serializeNulls is false, it should skip the name and the value
        writer.nullValue();

        // The deferredName should be cleared, and nothing should be written to the output for this call
        assertEquals("", out.toString());

        // Verify that the writer is still functional and deferredName was cleared by writing something else
        writer.value("nextValue");
        // If deferredName was cleared, it should just write the next value (depending on context, 
        // but here we just check if it didn't crash and didn't print "testKey")
        assertFalse(out.toString().contains("testKey"));
    }

    @Test
    public void testNullValue_Chainability() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        // Test that it returns this (chaining)
        writer.beginObject().name("a").nullValue().endObject();

        assertEquals("{\"a\":null}", out.toString());
    }
}
